import './neon-image.scss';
import { NeonWidget } from '../shared/neon-widget';
import { updateDynamicAttribute, dynamicAttr, createElementIf, updateConditionalElements, classNames } from '../shared/dom-manipulation';
import { stringHasCharacters } from '../shared/string-utils';
export class NeonImage extends NeonWidget {
    constructor() {
        super(...arguments);
        this.widgetTag = 'neon-image';
        this.mediaImageFailure = false;
    }
    //Any attribute that should be watched for changes should be listed here.
    static get observedAttributes() {
        return [
            'data-src',
            'data-alt',
            'data-object-fit'
        ];
    }
    //when the attributes change this will run
    attributeChanged(attrName, oldVal, newVal) {
        super.attributeChanged(attrName, oldVal, newVal);
        // attributeChanged is called when attributes listed in "static get observedAttributes()" are changed.
        switch (attrName) {
            case 'data-src':
                this.mediaImageFailure = false;
                updateDynamicAttribute(this, 'src');
                updateConditionalElements(this);
                break;
            case 'data-alt':
                updateDynamicAttribute(this, 'alt');
                break;
            case 'data-object-fit':
                updateDynamicAttribute(this, 'class');
                break;
            default:
        }
    }
    validateInputs() {
        super.validateInputs();
        if (!stringHasCharacters(this.getAttribute('data-src'))) {
            console.error('The "data-src" attribute is not set.');
        }
        // undefined         true  && true => error
        // ''                false && true => no error
        // ' '               true  && true => error
        // 'butterfly'       true  && false => no error
        if (this.getAttribute('data-alt') !== '' && !stringHasCharacters(this.getAttribute('data-alt'))) {
            console.error('The "data-alt" attribute is not set.');
        }
    }
    renderConditionalImage() {
        return createElementIf(() => { return this.mediaImageFailure === false && this.getAttribute('data-src') !== ''; }, 'img', {
            attrs: {
                class: dynamicAttr(() => {
                    return classNames({
                        'neon-image': true,
                        'neon-image-object-fit-contain': this.getAttribute('data-object-fit') === 'contain',
                        'neon-image-object-fit-cover': this.getAttribute('data-object-fit') !== 'contain',
                    });
                }),
                src: dynamicAttr(() => { return this.getAttribute('data-src'); }),
                alt: dynamicAttr(() => { return this.getAttribute('data-alt'); }),
            },
            listeners: {
                error: () => {
                    this.mediaImageFailure = true;
                    updateConditionalElements(this);
                },
                load: () => {
                    this.mediaImageFailure = false;
                    updateConditionalElements(this);
                }
            }
        });
    }
    renderConditionalFallbackImage() {
        return createElementIf(() => { return this.mediaImageFailure === true; }, 'img', {
            attrs: {
                class: 'neon-image',
                src: 'https://assets.powerschool.com/neon/unversioned/svg/illustration/image-fallback.svg',
                alt: dynamicAttr(() => { return this.getAttribute('data-alt'); }),
            }
        });
    }
    render() {
        return [
            this.renderConditionalImage(),
            this.renderConditionalFallbackImage()
        ];
    }
}
